begin;
create function public.mir_coordination_people(org uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare out jsonb;begin if not mir_core.coordination_allowed(org) then raise exception 'Coordination requise' using errcode='42501';end if;select coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'name',coalesce(p.name,u.raw_user_meta_data->>'full_name',case when m.role='admin' then 'Administration MIR' else 'Adjointe MIR' end))),'[]') into out from mir_core.memberships m join auth.users u on u.id=m.user_id left join mir_core.staff_profiles p on(p.organization_id,p.user_id)=(m.organization_id,m.user_id) where m.organization_id=org and m.active and (m.role='admin' or exists(select 1 from mir_core.coordination_access a where a.organization_id=org and a.user_id=m.user_id and a.active));return out;end$$;
create function public.mir_supplier_orders_list() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare org uuid;out jsonb;begin select organization_id into org from mir_core.account_settings where singleton;if not mir_core.coordination_allowed(org) then raise exception 'Coordination requise' using errcode='42501';end if;select coalesce(jsonb_agg(jsonb_build_object('id',id) order by created_at desc),'[]') into out from mir_core.orders where organization_id=org and kind='supplier';return out;end$$;
revoke all on function public.mir_coordination_people(uuid),public.mir_supplier_orders_list() from public,anon;grant execute on function public.mir_coordination_people(uuid),public.mir_supplier_orders_list() to authenticated;
-- All business writes now use the existing checked RPCs. Direct inserts cannot forge an approval/PDF.
revoke insert,update on mir_core.orders,mir_core.order_revisions,mir_core.order_lines,mir_core.order_events,mir_core.documents from authenticated;
commit;
